await import("/Users/berni/.codex/worktrees/e181/labs/packages/memory/test/v2-path.bench.ts");
const results = [];
for (let caseIndex = 0; caseIndex < 5; caseIndex++) {
  const arms = [registered[caseIndex], registered[caseIndex + 5]];
  let started = 0;
  let elapsed = 0;
  const context = {start() {started = performance.now()}, end() {elapsed += performance.now() - started}};
  for (let warm = 0; warm < 500; warm++) for (const arm of arms) arm.fn(context);
  const pairs = [];
  for (let pair = 0; pair < 20; pair++) {
    const sample = [0, 0];
    for (const side of pair % 2 === 0 ? [0, 1] : [1, 0]) {
      elapsed = 0;
      for (let batch = 0; batch < 25; batch++) arms[side].fn(context);
      sample[side] = elapsed / 25;
    }
    pairs.push(sample);
  }
  results.push({name: arms[0].name, pairs});
